// Mirror Landing v2
import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { translations, flags } from '../i18n';

function MirrorOrb({ size = 26 }) {
  return (
    <div style={{ width: `${size}px`, height: `${size}px`, borderRadius: '50%', background: 'radial-gradient(circle at 30% 28%, rgba(255,255,255,0.95) 0%, rgba(200,205,230,0.75) 18%, rgba(130,138,190,0.55) 40%, rgba(50,55,100,0.8) 65%, rgba(8,8,20,0.97) 100%)', boxShadow: '0 0 18px rgba(210,215,255,0.22)', position: 'relative', flexShrink: 0 }}>
      <div style={{ position: 'absolute', top: '16%', left: '20%', width: '24%', height: '24%', background: 'rgba(255,255,255,0.9)', borderRadius: '50%', filter: 'blur(2px)' }} />
    </div>
  );
}

function Universe() {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: 0, y: 0 });
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    let animId;
    const W = () => window.innerWidth;
    const H = () => window.innerHeight;
    canvas.width = W(); canvas.height = H();
    window.addEventListener('resize', () => { canvas.width = W(); canvas.height = H(); });
    window.addEventListener('mousemove', e => { mouseRef.current = { x: e.clientX, y: e.clientY }; });
    const stars = Array.from({ length: 260 }, () => ({
      x: Math.random() * W(), y: Math.random() * H(),
      r: Math.random() * 1.2 + 0.08,
      o: Math.random() * 0.45 + 0.04,
      ph: Math.random() * Math.PI * 2,
      sp: Math.random() * 0.005 + 0.002,
    }));
    let t = 0;
    const draw = () => {
      const w = W(), h = H();
      ctx.clearRect(0, 0, w, h);
      const g = ctx.createRadialGradient(w * .5, h * .08, 0, w * .5, h * .08, w * .7);
      g.addColorStop(0, 'rgba(140,148,210,0.04)'); g.addColorStop(1, 'transparent');
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
      const { x: mx, y: my } = mouseRef.current;
      if (mx && my) {
        const g2 = ctx.createRadialGradient(mx, my, 0, mx, my, 280);
        g2.addColorStop(0, 'rgba(180,185,230,0.025)'); g2.addColorStop(1, 'transparent');
        ctx.fillStyle = g2; ctx.fillRect(0, 0, w, h);
      }
      stars.forEach(s => {
        const p = s.o + Math.sin(t * s.sp + s.ph) * 0.14;
        ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(208,212,242,${p})`; ctx.fill();
      });
      t++; animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, []);
  return <canvas ref={canvasRef} style={{ position: 'fixed', inset: 0, zIndex: 0, pointerEvents: 'none' }} />;
}

export default function Landing() {
  const navigate = useNavigate();
  const [loaded, setLoaded] = useState(false);
  const [lang, setLang] = useState('pt');
  const [langOpen, setLangOpen] = useState(false);
  const t = translations[lang];

  useEffect(() => { setTimeout(() => setLoaded(true), 100); }, []);

  const steps = [
    { n: '01', title: t.s1t, desc: t.s1d },
    { n: '02', title: t.s2t, desc: t.s2d },
    { n: '03', title: t.s3t, desc: t.s3d },
  ];

  return (
    <div style={{ minHeight: '100vh', background: '#040408', color: 'white', overflowX: 'hidden', fontFamily: 'sans-serif' }}>
      <Universe />
      <div style={{ position: 'fixed', inset: 0, background: 'radial-gradient(ellipse 100% 60% at 50% 0%, rgba(120,125,200,0.07) 0%, transparent 60%)', zIndex: 1, pointerEvents: 'none' }} />

      <header style={{ position: 'fixed', top: 0, left: 0, right: 0, zIndex: 200, padding: '22px 48px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(4,4,8,0.6)', backdropFilter: 'blur(40px)', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '13px' }}>
          <MirrorOrb size={26} />
          <span style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1rem', letterSpacing: '7px', opacity: 0.75 }}>Mirror</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ position: 'relative' }}>
            <button onClick={() => setLangOpen(!langOpen)} style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.07)', color: 'rgba(255,255,255,0.38)', padding: '6px 13px', borderRadius: '20px', cursor: 'pointer', fontSize: '0.7rem', letterSpacing: '1.5px', display: 'flex', alignItems: 'center', gap: '6px' }}>
              <span>{flags[lang].label}</span>
              <span style={{ fontSize: '0.55rem', opacity: 0.5 }}>▾</span>
            </button>
            {langOpen && (
              <div style={{ position: 'absolute', top: '38px', right: 0, background: 'rgba(8,8,18,0.97)', border: '1px solid rgba(255,255,255,0.07)', borderRadius: '12px', overflow: 'hidden', minWidth: '90px', backdropFilter: 'blur(20px)', boxShadow: '0 20px 60px rgba(0,0,0,0.6)' }}>
                {Object.entries(flags).map(([code, { label }]) => (
                  <button key={code} onClick={() => { setLang(code); setLangOpen(false); }} style={{ display: 'block', width: '100%', padding: '10px 16px', background: lang === code ? 'rgba(255,255,255,0.05)' : 'transparent', border: 'none', color: lang === code ? 'rgba(220,225,255,0.85)' : 'rgba(255,255,255,0.4)', cursor: 'pointer', fontSize: '0.72rem', letterSpacing: '1.5px', textAlign: 'left', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                    {label}
                  </button>
                ))}
              </div>
            )}
          </div>
          <button onClick={() => navigate('/login')} style={{ background: 'transparent', border: '1px solid rgba(255,255,255,0.1)', color: 'rgba(255,255,255,0.4)', padding: '8px 20px', borderRadius: '30px', cursor: 'pointer', fontSize: '0.72rem', letterSpacing: '2px' }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.25)'; e.currentTarget.style.color = 'rgba(255,255,255,0.75)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.1)'; e.currentTarget.style.color = 'rgba(255,255,255,0.4)'; }}
          >{t.login}</button>
          <button onClick={() => navigate('/register')} style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.16)', color: 'rgba(255,255,255,0.85)', padding: '8px 20px', borderRadius: '30px', cursor: 'pointer', fontSize: '0.72rem', letterSpacing: '2px', backdropFilter: 'blur(10px)' }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.1)'; e.currentTarget.style.borderColor = 'rgba(255,255,255,0.3)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.06)'; e.currentTarget.style.borderColor = 'rgba(255,255,255,0.16)'; }}
          >{t.register}</button>
        </div>
      </header>

      <section style={{ position: 'relative', zIndex: 10, minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '120px 30px 80px', opacity: loaded ? 1 : 0, transform: loaded ? 'none' : 'translateY(32px)', transition: 'opacity 1.8s ease, transform 1.8s ease' }}>
        <div style={{ position: 'relative', width: '240px', height: '240px', margin: '0 auto 68px' }}>
          {[234, 160, 118].map((size, i) => (
            <div key={i} style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: `${size}px`, height: `${size}px`, borderRadius: '50%', border: `0.5px solid rgba(255,255,255,${[0.025, 0.055, 0.1][i]})`, animation: i < 2 ? `rp 7s ease-in-out ${[2, 0][i]}s infinite` : 'none' }} />
          ))}
          <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: '88px', height: '88px', borderRadius: '50%', background: 'radial-gradient(circle at 29% 24%, rgba(255,255,255,0.97) 0%, rgba(205,210,235,0.78) 16%, rgba(135,142,200,0.58) 38%, rgba(48,52,100,0.82) 64%, rgba(6,6,18,0.97) 100%)', boxShadow: '0 0 80px rgba(200,210,255,0.12), 0 0 160px rgba(150,158,220,0.06)' }} />
          {[{ dur: '11s', dir: 'normal', size: 5, op: 0.75 }, { dur: '17s', dir: 'reverse', size: 3, op: 0.45 }].map((o, i) => (
            <div key={i} style={{ position: 'absolute', top: '50%', left: '50%', width: '160px', height: '160px', margin: '-80px 0 0 -80px', borderRadius: '50%', animation: `spin ${o.dur} linear ${o.dir} infinite` }}>
              <div style={{ position: 'absolute', top: `-${o.size / 2 + 0.5}px`, left: '50%', transform: 'translateX(-50%)', width: `${o.size}px`, height: `${o.size}px`, borderRadius: '50%', background: `rgba(215,220,255,${o.op})`, boxShadow: `0 0 7px rgba(215,220,255,${o.op * 0.8})` }} />
            </div>
          ))}
        </div>

        <p style={{ fontSize: '0.6rem', letterSpacing: '5px', color: 'rgba(255,255,255,0.18)', textTransform: 'uppercase', marginBottom: '26px' }}>{t.tagline}</p>
        <h1 style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: 'clamp(2.6rem,7vw,5.6rem)', fontWeight: '400', lineHeight: 1.0, marginBottom: '28px', letterSpacing: '-1.5px' }}>
          {t.h1line1}<br />
          <span style={{ background: 'linear-gradient(135deg, #ffffff 0%, rgba(208,214,242,0.88) 35%, rgba(160,168,228,0.72) 70%, rgba(110,120,200,0.55) 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>{t.h1line2}</span>
        </h1>
        <p style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1rem', fontStyle: 'italic', color: 'rgba(255,255,255,0.26)', maxWidth: '400px', lineHeight: 2.1, marginBottom: '14px' }}>{t.sub}</p>
        <p style={{ fontSize: '0.7rem', color: 'rgba(255,255,255,0.13)', letterSpacing: '2px', marginBottom: '52px' }}>{t.sub2}</p>

        <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', justifyContent: 'center', marginBottom: '16px' }}>
          <button onClick={() => navigate('/register')} style={{ background: 'rgba(255,255,255,0.055)', border: '1px solid rgba(255,255,255,0.16)', color: 'rgba(255,255,255,0.88)', padding: '17px 54px', borderRadius: '50px', cursor: 'pointer', fontSize: '0.78rem', letterSpacing: '3px', backdropFilter: 'blur(20px)' }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.09)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.055)'; }}
          >{t.ctaMain}</button>
          <button onClick={() => navigate('/login')} style={{ background: 'transparent', border: '1px solid rgba(255,255,255,0.08)', color: 'rgba(255,255,255,0.38)', padding: '17px 36px', borderRadius: '50px', cursor: 'pointer', fontSize: '0.78rem', letterSpacing: '2.5px' }}
            onMouseEnter={e => { e.currentTarget.style.color = 'rgba(255,255,255,0.65)'; }}
            onMouseLeave={e => { e.currentTarget.style.color = 'rgba(255,255,255,0.38)'; }}
          >{t.ctaLogin}</button>
        </div>
        <span style={{ fontSize: '0.65rem', color: 'rgba(255,255,255,0.1)', letterSpacing: '1.5px' }}>{t.hint}</span>

        <div style={{ position: 'absolute', bottom: '34px', left: '50%', transform: 'translateX(-50%)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '7px', opacity: 0.16 }}>
          <span style={{ fontSize: '0.58rem', letterSpacing: '3px', textTransform: 'uppercase' }}>{t.explore}</span>
          <div style={{ width: '1px', height: '42px', background: 'linear-gradient(to bottom,rgba(255,255,255,0.5),transparent)', animation: 'scrollAnim 2.6s ease-in-out infinite' }} />
        </div>
      </section>

      <section style={{ position: 'relative', zIndex: 10, maxWidth: '980px', margin: '0 auto', padding: '80px 30px 100px' }}>
        <p style={{ textAlign: 'center', fontSize: '0.6rem', letterSpacing: '5px', color: 'rgba(255,255,255,0.13)', textTransform: 'uppercase', marginBottom: '60px' }}>{t.howLabel}</p>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: '1px', background: 'rgba(255,255,255,0.04)', borderRadius: '26px', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.05)' }}>
          {steps.map((st, i) => (
            <div key={i} style={{ background: 'linear-gradient(150deg,rgba(255,255,255,0.02),rgba(4,4,8,0.99))', padding: '46px 34px', position: 'relative' }}>
              <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '1px', background: 'linear-gradient(90deg,transparent,rgba(255,255,255,0.07),transparent)' }} />
              <p style={{ fontSize: '0.58rem', color: 'rgba(255,255,255,0.15)', letterSpacing: '4px', marginBottom: '20px' }}>{st.n}</p>
              <h3 style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1.1rem', fontWeight: '400', marginBottom: '12px', color: 'rgba(255,255,255,0.75)' }}>{st.title}</h3>
              <p style={{ fontSize: '0.82rem', color: 'rgba(255,255,255,0.22)', lineHeight: 2.05, fontWeight: '300' }}>{st.desc}</p>
            </div>
          ))}
        </div>
      </section>

      <div style={{ position: 'relative', zIndex: 10, maxWidth: '680px', margin: '0 auto', padding: '0 30px 110px' }}>
        <div style={{ background: 'linear-gradient(155deg,rgba(255,255,255,0.025),rgba(255,255,255,0.008))', border: '1px solid rgba(255,255,255,0.065)', borderRadius: '22px', padding: '50px', position: 'relative' }}>
          <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '1px', background: 'linear-gradient(90deg,transparent,rgba(255,255,255,0.1),transparent)' }} />
          <p style={{ fontSize: '0.58rem', letterSpacing: '4px', color: 'rgba(255,255,255,0.17)', textTransform: 'uppercase', marginBottom: '26px' }}>{t.iLabel}</p>
          <p style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1.08rem', fontStyle: 'italic', color: 'rgba(255,255,255,0.46)', lineHeight: 1.95, marginBottom: '26px' }}>{t.iText}</p>
          <div style={{ width: '36px', height: '1px', background: 'rgba(255,255,255,0.1)', marginBottom: '18px' }} />
          <p style={{ fontSize: '0.78rem', color: 'rgba(255,255,255,0.18)', lineHeight: 1.85 }}>{t.iSub}</p>
        </div>
      </div>

      <div style={{ position: 'relative', zIndex: 10, textAlign: 'center', padding: '0 30px 130px', maxWidth: '580px', margin: '0 auto' }}>
        <div style={{ width: '1px', height: '66px', background: 'linear-gradient(to bottom,transparent,rgba(255,255,255,0.11))', margin: '0 auto 46px' }} />
        <p style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: 'clamp(1rem,2.4vw,1.28rem)', fontStyle: 'italic', color: 'rgba(255,255,255,0.28)', lineHeight: 1.95, marginBottom: '18px' }}>{t.quoteText}</p>
        <span style={{ fontSize: '0.6rem', color: 'rgba(255,255,255,0.1)', letterSpacing: '4px', textTransform: 'uppercase' }}>{t.quoteAuthor}</span>
        <div style={{ width: '1px', height: '66px', background: 'linear-gradient(to bottom,rgba(255,255,255,0.11),transparent)', margin: '46px auto 0' }} />
      </div>

      <div style={{ position: 'relative', zIndex: 10, textAlign: 'center', padding: '0 30px 150px' }}>
        <h2 style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: 'clamp(1.7rem,4vw,2.9rem)', fontWeight: '400', marginBottom: '14px', color: 'rgba(255,255,255,0.6)', lineHeight: 1.2 }}>{t.cta2h}</h2>
        <p style={{ fontSize: '0.82rem', fontStyle: 'italic', color: 'rgba(255,255,255,0.16)', marginBottom: '42px' }}>{t.cta2p}</p>
        <button onClick={() => navigate('/register')} style={{ background: 'transparent', border: '1px solid rgba(255,255,255,0.12)', color: 'rgba(255,255,255,0.45)', padding: '14px 46px', borderRadius: '40px', cursor: 'pointer', fontSize: '0.75rem', letterSpacing: '2px' }}
          onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.25)'; e.currentTarget.style.color = 'rgba(255,255,255,0.7)'; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'; e.currentTarget.style.color = 'rgba(255,255,255,0.45)'; }}
        >{t.cta2btn}</button>
      </div>

      <footer style={{ position: 'relative', zIndex: 10, borderTop: '1px solid rgba(255,255,255,0.04)', padding: '26px 48px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '9px' }}>
          <div style={{ width: '4px', height: '4px', borderRadius: '50%', background: 'rgba(255,255,255,0.18)' }} />
          <span style={{ fontSize: '0.65rem', color: 'rgba(255,255,255,0.1)', letterSpacing: '2px' }}>© 2026 MIRROR</span>
        </div>
        <span style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '0.72rem', color: 'rgba(255,255,255,0.1)', fontStyle: 'italic' }}>{t.footer}</span>
      </footer>

      <style>{`
        @keyframes rp { 0%,100%{opacity:0.55;transform:translate(-50%,-50%) scale(1)} 50%{opacity:0.9;transform:translate(-50%,-50%) scale(1.04)} }
        @keyframes spin { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
        @keyframes scrollAnim { 0%,100%{opacity:0;transform:scaleY(0.2);transform-origin:top} 50%{opacity:1;transform:scaleY(1)} }
        * { box-sizing: border-box; }
      `}</style>
    </div>
  );
}
